import { createRequire } from 'node:module';
import { expect } from '@playwright/test';
import { otworzBadania, otworzSejf, sekcjaBadan } from './lab-historia-dane.mjs';
import { createKlirensSearchEnvironment } from './klirens-search-all-formulas.mjs';

const require = createRequire(import.meta.url);
const puberty = require('../../vilda_lab_puberty.js');
const pubertyData = require('../../vilda_lab_puberty_data.js');
const snapshot = require('../../vilda_lab_snapshot.js');
const DATES = ['2026-02-25', '2026-04-08', '2026-06-02'];

// Fictional observations, generated by the real clinical producers and saved
// through the real vault. No live patient state or I/O is replaced.
function laboratoryRecords() {
  const notes = [];
  for (let index = 0; index < DATES.length; index++) {
    const date = DATES[index];
    const value = [0.3, 2.1, 6.2][index];
    notes.push({ key: 'tsh-' + index, category: 'wynik-badania', title: 'Fikcyjna kontrola TSH', body: '', clinicalDateISO: date,
      labResult: { test: 'TSH (tyreotropina)', testKey: 'tsh', value: String(value), valueNum: value, unit: 'mIU/L', norm: '0,6–4,5 mIU/L' } });
    for (const analyte of ['lh', 'fsh']) {
      const value = analyte === 'lh' ? [0.08, 0.12, 0][index] : [2.82, 3, 3.06][index];
      const evaluation = puberty.evaluate({ analyte, value: String(value), unit: 'IU/L', sex: 'M',
        birthDateISO: '2022-02-25', sampleDateISO: date, referenceSelection: 'automatic', contextBasis: 'current-patient', currentContextAvailable: true,
        specimen: 'unknown', measurementKind: 'unknown', assay: { profileId: '', methodId: '', confirmation: 'unknown' },
        treatment: { context: 'unknown', gnrha: 'unknown', sexSteroids: 'unknown' },
        puberty: { kind: 'G', stage: 1, appliesToCurrentContext: true, observationProvided: true } }, pubertyData);
      const saved = snapshot.create(evaluation);
      if (saved.status !== 'recorded') throw new Error('Fictional limited snapshot was not recorded: ' + analyte);
      notes.push({ key: analyte + '-' + index, category: 'wynik-badania', title: 'Fikcyjny wynik ' + analyte.toUpperCase(), body: '', clinicalDateISO: date,
        labResult: { test: analyte === 'lh' ? 'LH (hormon luteinizujący)' : 'FSH (hormon folikulotropowy)', testKey: analyte,
          value: String(value), valueNum: value, unit: 'IU/L', assessment: saved } });
    }
  }
  const date = '2026-05-06';
  const evaluation = puberty.evaluate({ analyte: 'lh', value: '2', unit: 'IU/L', sex: 'M',
    birthDateISO: '2020-05-06', sampleDateISO: date, specimen: 'serum', measurementKind: 'basal',
    assay: { profileId: 'mayo-lh-pediatric', methodId: 'anshlite-lh-clia', confirmation: 'reported' },
    puberty: { kind: 'G', stage: 4, assessedAtISO: date, appliesToSample: true, source: 'fictional-examination' },
    treatment: { gnrha: 'no', sexSteroids: 'no' }, preterm: 'no' }, pubertyData);
  const saved = snapshot.create(evaluation);
  if (saved.status !== 'recorded' || saved.evaluation.clinical.status !== 'warning') throw new Error('Fictional clinical warning fixture is not meaningful');
  notes.push({ key: 'lh-clinical', category: 'wynik-badania', title: 'Fikcyjny wynik z zapisaną oceną kliniczną', body: '', clinicalDateISO: date,
    labResult: { test: 'LH (hormon luteinizujący)', testKey: 'lh', value: '2', valueNum: 2, unit: 'IU/L', assessment: saved } });
  return notes;
}

function renalRecords(patientId) {
  const root = createKlirensSearchEnvironment();
  const parameter = root.ClcrSavedResults.getParam('AGu_spot');
  return DATES.map((date, index) => {
    const result = root.VildaClcrUag.evaluate({ urineSodium: '40', urinePotassium: '30', urineChloride: String([62, 74, 82][index]) }, root.VildaClcrUagReferenceData.DEFAULT_POLICY);
    const point = { ...parameter, parameterKey: parameter.id, valueNum: result.rawValue };
    root.ClcrUagPersistence.augmentDatapoint({ getAttribute: key => key === 'data-clcr-uag-snapshot' ? JSON.stringify(result) : null }, point);
    const note = root.ClcrSavedResults.buildPatientNotePayload(point, { patientId, clinicalDateISO: date });
    const check = root.ClcrSavedResults.projectPatientNotes([{ ...note, id: 'fictional-check-' + index }], { patientId });
    if (check.measurements[0]?.status !== 'recorded') throw new Error('Fictional UAG must retain its recorded assessment');
    return { ...note, key: 'uag-' + index };
  });
}

async function seed(page) {
  const patientId = await otworzSejf(page);
  const records = laboratoryRecords().concat(renalRecords(patientId));
  const ids = await page.evaluate(async ({ patientId, records }) => {
    const ids = {};
    for (const record of records) {
      const { key, ...payload } = record;
      ids[key] = (await window.VildaVault.savePatientNote({ ...payload, patientId })).id;
    }
    return ids;
  }, { patientId, records });
  await otworzBadania(page, patientId);
  return { patientId, ids };
}

async function savedDigest(page, patientId) {
  return page.evaluate(async id => {
    const notes = await window.VildaVault.listPatientNotesForPatient(id);
    const bytes = new TextEncoder().encode(JSON.stringify(notes.slice().sort((a, b) => a.id.localeCompare(b.id))));
    return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)), value => value.toString(16).padStart(2, '0')).join('');
  }, patientId);
}

async function arrowGeometry(section) {
  const result = await section.locator('.vilda-lab-hist-select-wrap').evaluate(wrap => {
    const select = wrap.querySelector('select'), arrow = wrap.querySelector('.vilda-lab-hist-select-arrow');
    const a = arrow.getBoundingClientRect(), s = select.getBoundingClientRect();
    return { width: a.width, height: a.height, rightGap: s.right - a.right,
      middleDifference: (a.top + a.bottom - s.top - s.bottom) / 2,
      appearance: getComputedStyle(select).appearance, pointerEvents: getComputedStyle(arrow).pointerEvents };
  });
  expect(result).toMatchObject({ width: 16, height: 16, appearance: 'none', pointerEvents: 'none' });
  expect(Math.abs(result.rightGap - 16)).toBeLessThanOrEqual(1);
  expect(Math.abs(result.middleDifference)).toBeLessThanOrEqual(1);
}

async function chartGeometry(section, ids) {
  const result = await section.evaluate(host => {
    const point = (node, x, y) => new DOMPoint(x, y).matrixTransform(node.getScreenCTM());
    return [...host.querySelectorAll('.vilda-lab-result-chart-point[data-note-id]')].map(control => {
      const chart = control.closest('.vilda-lab-result-chart');
      const id = control.getAttribute('data-note-id');
      const guide = [...chart.querySelectorAll('.vilda-lab-result-chart-guide')].find(node => node.getAttribute('data-note-id') === id);
      const date = control.getAttribute('data-date');
      const label = [...chart.querySelectorAll('.vilda-lab-result-chart-date')].find(node => node.getAttribute('datetime') === date);
      const dot = control.querySelector('.vilda-lab-result-chart-dot'), rect = dot.getBoundingClientRect(), target = control.getBoundingClientRect();
      const style = getComputedStyle(dot);
      const begin = guide && point(guide, guide.x1.baseVal.value, guide.y1.baseVal.value);
      const labelRect = label?.getBoundingClientRect();
      return { id, tone: control.getAttribute('data-tone'), targetWidth: target.width, targetHeight: target.height, fill: style.backgroundColor, border: style.borderTopColor,
        guideExists: !!guide, labelExists: !!label,
        guideDx: begin ? Math.abs(begin.x - (rect.left + rect.width / 2)) : null,
        guideDy: begin ? Math.abs(begin.y - (rect.top + rect.height / 2)) : null,
        labelDx: labelRect ? Math.abs(labelRect.left + labelRect.width / 2 - (rect.left + rect.width / 2)) : null,
        dashed: guide && getComputedStyle(guide).strokeDasharray,
        day: label?.querySelector('.vilda-lab-result-chart-date-day')?.textContent,
        year: label?.querySelector('.vilda-lab-result-chart-date-year')?.textContent };
    });
  });
  expect(result.length).toBeGreaterThanOrEqual(12);
  for (const analyte of ['lh', 'fsh']) for (let index = 0; index < 3; index++) {
    expect(result.find(row => row.id === ids[analyte + '-' + index])?.tone, analyte + ' limited reference stays neutral on the chart').toBe('neutral');
  }
  for (const row of result) {
    expect(row.guideExists, row.id).toBe(true);
    expect(row.labelExists, row.id).toBe(true);
    expect(row.targetWidth, row.id).toBeGreaterThanOrEqual(44);
    expect(row.targetHeight, row.id).toBeGreaterThanOrEqual(44);
    expect(row.fill, row.id).not.toBe('rgba(0, 0, 0, 0)');
    expect(row.fill, row.id).not.toBe('rgb(255, 255, 255)');
    expect(row.fill, row.id).toBe(row.border);
    if (['above', 'below'].includes(row.tone)) expect(row.fill, row.id).toBe('rgb(207, 34, 46)');
    if (row.tone === 'within') expect(row.fill, row.id).toBe('rgb(8, 127, 91)');
    expect(row.guideDx, row.id).toBeLessThanOrEqual(1);
    expect(row.guideDy, row.id).toBeLessThanOrEqual(1);
    expect(row.labelDx, row.id).toBeLessThanOrEqual(1);
    expect(row.dashed, row.id).not.toBe('none');
    expect(row.day, row.id).toMatch(/^\d{2}\.\d{2}$/);
    expect(row.year, row.id).toBe('2026');
  }
}

async function toggleWithoutJump(page, section, mode) {
  const control = section.locator(`.vilda-lab-hist-segment-btn[data-view="${mode}"]`);
  await control.evaluate(button => {
    const root = button.closest('.vilda-auth-root');
    const target = root.scrollTop + button.getBoundingClientRect().top - root.getBoundingClientRect().top - 24;
    root.scrollTop = Math.min(root.scrollHeight - root.clientHeight, Math.max(0, target));
  });
  await expect(control).toBeInViewport();
  const before = await control.evaluate(button => {
    const root = button.closest('.vilda-auth-root');
    const ancestors = [];
    for (let node = button; node; node = node.parentElement) {
      const rect = node.getBoundingClientRect();
      ancestors.push({ name: node.tagName + '.' + node.className, top: rect.top, height: rect.height, scroll: node.scrollTop, clientHeight: node.clientHeight, scrollHeight: node.scrollHeight,
        overflowY: getComputedStyle(node).overflowY, alignItems: getComputedStyle(node).alignItems, scrollBehavior: getComputedStyle(node).scrollBehavior });
    }
    const rect = button.getBoundingClientRect();
    const hit = document.elementFromPoint(rect.left + rect.width / 2, rect.top + rect.height / 2);
    const capture = () => ({ top: button.getBoundingClientRect().top, left: button.getBoundingClientRect().left, scroll: root.scrollTop, maxScroll: root.scrollHeight - root.clientHeight });
    button.__labE2EPointerMetrics = {};
    button.addEventListener('pointerdown', () => { button.__labE2EPointerMetrics.pointerdown = capture(); }, { capture: true, once: true });
    button.addEventListener('click', () => { button.__labE2EPointerMetrics.click = capture(); }, { capture: true, once: true });
    return { top: rect.top, left: rect.left, width: rect.width, height: rect.height, scroll: root.scrollTop, documentScroll: document.scrollingElement.scrollTop,
      maxScroll: root.scrollHeight - root.clientHeight, rootTop: root.getBoundingClientRect().top, rootHeight: root.clientHeight, ancestors,
      panel: button.closest('.vilda-lab-hist').querySelector('.vilda-lab-hist-panel-select').value, hit: hit === button || button.contains(hit) };
  });
  await control.click();
  await expect(control).toHaveAttribute('aria-pressed', 'true');
  await expect(control).toBeFocused();
  await page.evaluate(() => new Promise(resolve => { requestAnimationFrame(() => { requestAnimationFrame(resolve); }); }));
  const after = await control.evaluate(button => {
    const root = button.closest('.vilda-auth-root');
    const ancestors = [];
    for (let node = button; node; node = node.parentElement) {
      const rect = node.getBoundingClientRect();
      ancestors.push({ name: node.tagName + '.' + node.className, top: rect.top, height: rect.height, scroll: node.scrollTop, clientHeight: node.clientHeight, scrollHeight: node.scrollHeight,
        overflowY: getComputedStyle(node).overflowY, alignItems: getComputedStyle(node).alignItems, scrollBehavior: getComputedStyle(node).scrollBehavior });
    }
    return { top: button.getBoundingClientRect().top, left: button.getBoundingClientRect().left, scroll: root.scrollTop, documentScroll: document.scrollingElement.scrollTop,
      maxScroll: root.scrollHeight - root.clientHeight, rootTop: root.getBoundingClientRect().top, rootHeight: root.clientHeight, ancestors, pointer: button.__labE2EPointerMetrics };
  });
  const context = JSON.stringify({ mode, before, after });
  expect(before.hit, context).toBe(true);
  if (page.viewportSize().width <= 600) {
    expect(before.width, context + ' touch target width').toBeGreaterThanOrEqual(44);
    expect(before.height, context + ' touch target height').toBeGreaterThanOrEqual(44);
  }
  for (const key of ['top', 'left', 'scroll']) expect(Math.abs(after.pointer.pointerdown[key] - before[key]), context + ' pointerdown ' + key).toBeLessThanOrEqual(1);
  for (const key of ['top', 'left', 'scroll', 'documentScroll']) expect(Math.abs(after[key] - before[key]), context + ' ' + key).toBeLessThanOrEqual(1);
  return before;
}

export async function verifyPresentationControls(page, width, height) {
  await page.setViewportSize({ width, height });
  const { patientId, ids } = await seed(page);
  const section = sekcjaBadan(page), source = section.getByRole('combobox', { name: 'Panel badań', exact: true });
  const before = await savedDigest(page, patientId);
  await expect(section.getByRole('heading', { name: 'Wyniki badań', exact: true })).toBeVisible();
  await expect(source.locator('option[value="all"]')).toHaveText('Wszystkie wyniki');
  await expect(source.locator('option[value="lab"]')).toHaveText('Wyniki lab.');
  await expect(source.locator('option[value="renal"]')).toHaveText('Klirens');
  await source.selectOption('all');
  await expect(section.locator('.vilda-lab-hist-result-row')).toHaveCount(13);
  await arrowGeometry(section);
  await source.selectOption('lab');
  await expect(section.locator('.vilda-lab-hist-result-row')).toHaveCount(10);
  await arrowGeometry(section);
  for (const [index, tone, symbol, color] of [[0, 'below', '↓', 'rgb(207, 34, 46)'], [1, 'within', '', 'rgb(8, 127, 91)'], [2, 'above', '↑', 'rgb(207, 34, 46)']]) {
    const row = section.locator(`.vilda-lab-hist-result-row[data-note-id="${ids['tsh-' + index]}"]`);
    const value = row.locator('.vilda-lab-hist-cell-value');
    await expect(value).toHaveClass(new RegExp('tone-' + tone));
    expect(await value.evaluate(node => getComputedStyle(node).color)).toBe(color);
    if (symbol) await expect(row.locator('.vilda-lab-hist-flag')).toHaveText(symbol);
    else await expect(row.locator('.vilda-lab-hist-flag')).toHaveCount(0);
  }
  for (const analyte of ['lh', 'fsh']) for (let index = 0; index < 3; index++) {
    const row = section.locator(`.vilda-lab-hist-result-row[data-note-id="${ids[analyte + '-' + index]}"]`);
    await expect(row.locator('.vilda-lab-hist-cell-value')).toHaveClass(/tone-neutral/);
    await expect(row.locator('.vilda-lab-hist-flag')).toHaveCount(0);
    await expect(row.locator('.vilda-lab-hist-reference-note')).not.toBeEmpty();
  }
  const clinical = section.locator(`.vilda-lab-hist-result-row[data-note-id="${ids['lh-clinical']}"]`);
  await expect(clinical.locator('.vilda-lab-hist-result-notice[data-warning-kind="clinical"]')).toBeVisible();
  await expect(clinical.locator('.vilda-lab-hist-result-notice[data-warning-kind="clinical"]')).not.toBeEmpty();
  await expect(clinical.locator('.vilda-lab-hist-flag').filter({ hasText: '!' })).toHaveCount(0);
  await source.selectOption('renal');
  await expect(section.locator('.vilda-lab-hist-result-row')).toHaveCount(3);
  await arrowGeometry(section);
  await source.selectOption('all');
  const positions = [await toggleWithoutJump(page, section, 'charts')];
  const connect = section.getByRole('checkbox', { name: 'Połącz punkty', exact: true });
  await expect(connect).toBeChecked();
  await chartGeometry(section, ids);
  const uag = section.locator('.vilda-lab-hist-card').filter({ has: page.locator(`.vilda-lab-result-chart-point[data-note-id="${ids['uag-2']}"]`) });
  const tsh = section.locator('.vilda-lab-hist-card[data-series="tsh"]');
  await expect(uag.locator('.vilda-lab-result-chart-line')).toHaveCount(2);
  await expect(tsh.locator('.vilda-lab-result-chart-line')).toHaveCount(2);
  await connect.uncheck();
  await expect(uag.locator('.vilda-lab-result-chart-line')).toHaveCount(0);
  await expect(tsh.locator('.vilda-lab-result-chart-line')).toHaveCount(0);
  await connect.check();
  await expect(uag.locator('.vilda-lab-result-chart-line')).toHaveCount(2);
  await expect(tsh.locator('.vilda-lab-result-chart-line')).toHaveCount(2);
  for (const panel of ['all', 'lab', 'renal', 'thyroid']) {
    await source.selectOption(panel);
    positions.push(await toggleWithoutJump(page, section, 'table'));
    positions.push(await toggleWithoutJump(page, section, 'charts'));
    positions.push(await toggleWithoutJump(page, section, 'table'));
    await expect(source).toHaveValue(panel);
  }
  expect(positions.some(position => position.maxScroll > 1), 'the patient card genuinely scrolls').toBe(true);
  expect(positions.some(position => position.panel === 'renal' && position.scroll > 1 && Math.abs(position.top - position.rootTop - 24) <= 1), 'the short renal panel keeps the visible reading anchor in a genuinely scrolled patient card').toBe(true);
  const geometry = await section.evaluate(host => {
    const root = host.closest('.vilda-auth-root');
    return { pageOverflow: document.scrollingElement.scrollWidth > document.scrollingElement.clientWidth + 1,
      cardOverflow: root.scrollWidth > root.clientWidth + 1 };
  });
  expect(geometry).toEqual({ pageOverflow: false, cardOverflow: false });
  expect(await savedDigest(page, patientId)).toBe(before);
}
